  function getLang(){
    var l = null;
    try { l = localStorage.getItem(STORE); } catch(e){}
    return (LANGS.indexOf(l) >= 0) ? l : 'es';
  }
  window.getLang = getLang;

  function tr(key, lang){
    var e = T[key];
    if (!e) return null;
    return e[lang] || e.es || null;
  }
  window.tr = tr;

